#!/usr/bin/env python3
"""LibreTorrent per-route setup for route_16 (BencodeFileItem$1.<init>). Generated by
graphs/LibreTorrent/scratch/kiro/make_device_routes.py (Kiro, 2026-11-03).

Generates kiro_sample.torrent (lt_common.make_torrent) into --gen-dir; the fixture phase pushes it to /sdcard/Download/kiro_sample.torrent (ROUTES.csv fixtures: gen:kiro_sample.torrent).

Invoked by run_app.sh after `pm clear`, before the fixture phase and the route script:
    setup_route_16.py --package <pkg> --log <log> --outdir <dir> --gen-dir <dir> [--adb adb]
Any failure exits 1 (failed_at_step_0, setup_failed). UI-driving setups are recorded as
MMEX-B3-UIDRIVE in device/run_app.sh; this one ends on the launcher (HOME), and the route
script starts with its own launch.
"""

import argparse
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.dirname(HERE))))

import lt_common  # noqa: E402


def main(argv=None):
    p = argparse.ArgumentParser()
    p.add_argument("--package", default="org.proninyaroslav.libretorrent.debug")
    p.add_argument("--log", default=None)
    p.add_argument("--outdir", default=None)
    p.add_argument("--gen-dir", default=None)
    p.add_argument("--adb", default="adb")
    a = p.parse_args(argv)
    gen_dir = a.gen_dir or os.environ.get("GEN_DIR", "") or os.getcwd()
    os.makedirs(gen_dir, exist_ok=True)

    def log(msg):
        if a.log:
            with open(a.log, "a", encoding="utf-8") as f:
                f.write(msg + "\n")
        print(msg)

    path = lt_common.make_torrent(os.path.join(gen_dir, lt_common.TORRENT_FILE))
    log("generated " + path)
    return 0


if __name__ == "__main__":
    sys.exit(main())
